import re
from collections import Counter


def solution(text: str) -> dict:
    words = re.findall(r"[a-zA-Z]+", text)
    return dict(Counter(w.lower() for w in words))

def solution(text: str, shift: int) -> str:
    result = []
    for char in text:
        if 'a' <= char <= 'z':
            result.append(chr((ord(char) - ord('a') + shift) % 26 + ord('a')))
        elif 'A' <= char <= 'Z':
            result.append(chr((ord(char) - ord('A') + shift) % 26 + ord('A')))
        else:
            result.append(char)
    return "".join(result)

from urllib.parse import parse_qsl


def solution(qs: str) -> dict[str, str]:
