        qs = qs[1:]
    return dict(parse_qsl(qs, keep_blank_values=True))

def solution(d, parent_key='', sep='.'):
    items = {}
    for k, v in d.items():
        new_key = f"{parent_key}{sep}{k}" if parent_key else k
        if isinstance(v, dict):
            items.update(solution(v, new_key, sep=sep))
        else:
            items[new_key] = v
    return items

def solution(s: str) -> bool:
    if not s or any(c.isspace() for c in s):
        return False

    parts = s.split('@')
    if len(parts) != 2:
        return False

    local, domain = parts

    if not local:
        return False

    if not domain or '.' not in domain:
        return False

    if domain.startswith('.') or domain.endswith('.'):
        return False

    return True

import math

def solution(items, page, per_page):
    total_items = len(items)
    if total_items == 0 or per_page <= 0:
        return {'items': [], 'total_pages': 0}

    total_pages = math.ceil(total_items / per_page)

    if page < 1 or page > total_pages:
        return {'items': [], 'total_pages': total_pages}

    start = (page - 1) * per_page
    end = start + per_page

    return {
        'items': items[start:end],
        'total_pages': total_pages
    }

from collections import defaultdict

def solution(rows, key):
    """
    Groups a list of dicts by the value of a specific key.
    Returns a dict mapping value -> list of rows in original order.
    """
    grouped = defaultdict(list)
    for row in rows:
        if key in row:
            grouped[row[key]].append(row)
    return dict(grouped)

def solution(nums, k):
    if not nums or k <= 0 or len(nums) < k:
        return []

    current_sum = sum(nums[:k])
    averages = [current_sum / k]

    for i in range(len(nums) - k):
        current_sum = current_sum - nums[i] + nums[i + k]
        averages.append(current_sum / k)

    return averages

