import csv
import io

def solution(csv_text, column):
    f = io.StringIO(csv_text.strip())
    reader = csv.DictReader(f)
    total = 0.0
    has_values = False

    for row in reader:
        if column in row and row[column] is not None:
            val = row[column].strip()
            if val != "":
                try:
                    total += float(val)
                    has_values = True
                except ValueError:
                    pass

    return total if has_values else 0.0
